func TestOperatorReplayPreservesFailedEligibilityAndEveryExactRouteSiblingParity(t *testing.T) {
	type fixture struct {
		store completeOperatorReplayProofStore
		db    *sql.DB
	}
	for _, tc := range []struct {
		name string
		open func(*testing.T, context.Context) fixture
	}{{name: "sqlite", open: func(t *testing.T, ctx context.Context) fixture {
		s := storetest.StartSQLiteRuntimeStoreWithContext(t, ctx)
		return fixture{store: s, db: storetest.DatabaseForTest(s)}
	}}, {name: "postgres", open: func(t *testing.T, _ context.Context) fixture {
		_, db, cleanup := testutil.StartPostgres(t)
		t.Cleanup(cleanup)
		return fixture{store: storetest.AdmitPostgresRuntimeStore(t, db), db: db}
	}}} {
		t.Run(tc.name, func(t *testing.T) {
			ctx := testAuthorActivityContext(context.Background())
			f := tc.open(t, ctx)
			runID := uuid.NewString()
			bus, err := newScopedAPITestEventBus(t, f.store, runtimebus.EventBusOptions{ContractBundle: semanticview.Wrap(runStartTestBundle("scan.requested"))})
			if err != nil {
				t.Fatalf("NewEventBusWithOptions: %v", err)
			}
			const agentID = "route-sibling-replay-agent"
			identity := runtimebustest.IdentityForRun(t, runID, agentID, "target-flow/instance")
			ch := subscribeOperatorReplayIdentity(t, bus, identity)
			defer runtimebustest.UnsubscribeIdentity(bus, identity)
			parentID := uuid.NewString()
			originalID := uuid.NewString()
			createdAt := time.Unix(1700001400, 0).UTC()
			seedCompleteReplayRun(t, ctx, f.db, tc.name == "sqlite", runID, createdAt.Add(-time.Minute))
			if err := storetest.UpsertStaticAgentFixtureForSource(t, ctx, f.store, runtimemanager.PersistedAgent{Config: withAPITestIntent(t, runtimeactors.AgentConfig{Identity: identity, ID: agentID, Role: "observer", Type: "stub", Model: "regular", ExecutionMode: "live", ResolvedLLMBackend: "anthropic", FlowID: "target-flow", FlowPath: identity.FlowInstance(), Config: []byte(`{}`), Subscriptions: []string{"scan.requested"}}), Status: "active", HiredBy: "test", StartedAt: createdAt}, runStartTestSourceArtifactFact()); err != nil {
				t.Fatalf("UpsertAgent(%s): %v", identity, err)
			}
			firstProjection, err := events.NewDeliveryPayloadProjection(map[string]string{"route_marker": "first"})
			if err != nil {
				t.Fatal(err)
			}
			secondProjection, err := events.NewDeliveryPayloadProjection(map[string]string{"route_marker": "second"})
			if err != nil {
				t.Fatal(err)
			}
			routes := []events.DeliveryRoute{{Recipient: events.MustAgentDeliveryRecipient(agentID), AgentIdentity: identity, Target: events.MustExistingEntityTarget(events.RouteIdentity{FlowID: "target-flow", FlowInstance: identity.FlowInstance(), EntityID: uuid.NewString()}), Context: events.DeliveryContext{Reply: &events.ReplyContextRef{ID: "reply-first"}}, PayloadProjection: firstProjection}, {Recipient: events.MustAgentDeliveryRecipient(agentID), AgentIdentity: identity, Target: events.MustExistingEntityTarget(events.RouteIdentity{FlowID: "target-flow", FlowInstance: identity.FlowInstance(), EntityID: uuid.NewString()}), Context: events.DeliveryContext{Reply: &events.ReplyContextRef{ID: "reply-second"}}, PayloadProjection: secondProjection}}
			parent := eventtest.InExecutionMode(eventtest.PersistedRuntimeControlForProducer(parentID, events.EventType("replay.parent"), eventtest.Producer(events.EventProducerPlatform, "replay-proof"), "", json.RawMessage(`{"parent":true}`), 0, runID, "", events.EventEnvelope{}, createdAt.Add(-time.Second)), "mock")
			original := eventtest.InExecutionMode(eventtest.PersistedChildForProducer(originalID, events.EventType("scan.requested"), eventtest.Producer(events.EventProducerAgent, "origin-agent"), "", json.RawMessage(`{"topic":"medicine"}`), 0, runID, parentID, events.EventEnvelope{Scope: events.EventScopeGlobal}, createdAt), "mock")
			storetest.CommitSemanticEvent(t, ctx, f.store, parent)
			storetest.CommitSemanticEventWithRoutes(t, ctx, f.store, original, routes, runtimepipelineobligation.ScopeSubscribed)
			firstClaim, err := storetest.ClaimDelivery(ctx, f.store, original, routes[0])
			if err != nil {
				t.Fatalf("claim delivered route: %v", err)
			}
			if _, err := f.store.SettleSuccess(ctx, firstClaim.Claim, nil, time.Millisecond, runtimedelivery.NotApplicableHandlerRuleSelection()); err != nil {
				t.Fatalf("settle delivered route: %v", err)
			}
			secondClaim, err := storetest.ClaimDelivery(ctx, f.store, original, routes[1])
			if err != nil {
				t.Fatalf("claim failed route: %v", err)
			}
			if snapshot, err := f.store.SettleFailure(ctx, secondClaim.Claim, runtimedelivery.Settlement{Disposition: runtimedelivery.FailureRetry, Failure: testFailure("handler_failed"), RetryBase: time.Hour, RuleSelection: runtimedelivery.NotApplicableHandlerRuleObservation()}); err != nil || snapshot.Status != runtimedelivery.StatusFailed || snapshot.Terminal() {
				t.Fatalf("settle retryable failed route snapshot=%#v err=%v", snapshot, err)
			}
			handler := completeOperatorReplayTestHandler(t, f.store, bus, createdAt.Add(time.Minute))
			response := rpcCall(t, handler, eventReplayBody(originalID, []string{agentID}, "exact-routes-"+tc.name))
			if response.Error != nil {
				t.Fatalf("event.replay error = %#v", response.Error)
			}
			result := asMap(t, response.Result)
			replayID := stringValue(t, result["replay_event_id"], "replay_event_id")
			originalRows := asSlice(t, result["original_deliveries"])
			newRows := asSlice(t, result["new_deliveries"])
			if len(originalRows) != 2 || len(newRows) != 2 {
				t.Fatalf("replay route rows original=%#v new=%#v, want two exact siblings", originalRows, newRows)
			}
			sourceByNew := map[string]string{}
			for _, raw := range newRows {
				row := asMap(t, raw)
				sourceByNew[fmt.Sprint(row["delivery_id"])] = fmt.Sprint(row["source_delivery_id"])
			}
			for _, route := range routes {
				originalDeliveryID, err := runtimedelivery.DeliveryID(originalID, route)
				if err != nil {
					t.Fatal(err)
				}
				newDeliveryID, err := runtimedelivery.DeliveryID(replayID, route)
				if err != nil {
					t.Fatal(err)
				}
				if got := sourceByNew[newDeliveryID]; got != originalDeliveryID {
					t.Fatalf("new delivery %s source = %q, want exact sibling %s", newDeliveryID, got, originalDeliveryID)
				}
			}
			persistedReplay, err := f.store.LoadOperatorEvent(ctx, replayID)
			if err != nil {
				t.Fatalf("LoadOperatorEvent replay: %v", err)
			}
			if len(persistedReplay.Deliveries) != 2 {
				t.Fatalf("persisted replay deliveries = %#v, want two", persistedReplay.Deliveries)
			}
			for _, route := range routes {
				matched := false
				for _, delivery := range persistedReplay.Deliveries {
					if events.SameDeliveryRouteIdentity(route, delivery.Route) {
						matched = true
						break
					}
				}
				if !matched {
					t.Fatalf("persisted replay omitted exact route %#v", route)
				}
			}
			received := map[string]events.Event{}
			for index := range routes {
				delivery := requireAPIV1RuntimeBusEvent(t, ch, "exact route sibling replay")
				var payload map[string]any
				if err := json.Unmarshal(delivery.Payload(), &payload); err != nil {
					t.Fatalf("decode projected payload %d: %v", index, err)
				}
				received[fmt.Sprint(payload["route_marker"])] = delivery
			}
			for index, marker := range []string{"first", "second"} {
				delivery, ok := received[marker]
				if !ok {
					t.Fatalf("received route markers = %#v, missing %s", received, marker)
				}
				if delivery.TargetRoute() != routes[index].Target.Route().Normalized() || delivery.DeliveryContext().ReplyContextID() != routes[index].Context.ReplyContextID() {
					t.Fatalf("received %s route target/context = %#v/%q, want %#v/%q", marker, delivery.TargetRoute(), delivery.DeliveryContext().ReplyContextID(), routes[index].Target, routes[index].Context.ReplyContextID())
				}
			}
			agentResponse := rpcCall(t, handler, agentReplayBodyWithRun(originalID, runID, agentID, "exact-agent-routes-"+tc.name))
			if agentResponse.Error != nil {
				t.Fatalf("agent.replay error = %#v", agentResponse.Error)
			}
			agentResult := asMap(t, agentResponse.Result)
			agentReplayID := stringValue(t, agentResult["replay_event_id"], "replay_event_id")
			agentOriginals := asSlice(t, agentResult["original_deliveries"])
			agentNew := asSlice(t, agentResult["new_deliveries"])
			if len(agentOriginals) != 2 || len(agentNew) != 2 {
				t.Fatalf("agent.replay route rows original=%#v new=%#v, want two exact siblings", agentOriginals, agentNew)
			}
			agentSourceByNew := map[string]string{}
			for _, raw := range agentNew {
				row := asMap(t, raw)
				agentSourceByNew[fmt.Sprint(row["delivery_id"])] = fmt.Sprint(row["source_delivery_id"])
			}
			for _, route := range routes {
				originalDeliveryID, err := runtimedelivery.DeliveryID(originalID, route)
				if err != nil {
					t.Fatal(err)
				}
				newDeliveryID, err := runtimedelivery.DeliveryID(agentReplayID, route)
				if err != nil {
					t.Fatal(err)
				}
				if got := agentSourceByNew[newDeliveryID]; got != originalDeliveryID {
					t.Fatalf("agent replay delivery %s source = %q, want %s", newDeliveryID, got, originalDeliveryID)
				}
			}
			for range routes {
				requireAPIV1RuntimeBusEvent(t, ch, "agent exact route sibling replay")
			}
		})
	}
}

