func TestRootToSingletonFirstDeliveryMaterializesReceiverEntityOnBothBackends(t *testing.T) {
	repoRoot := canonicalrouting.RepoRoot(t)
	bundle, err := runtimecontracts.LoadWorkflowContractBundleWithOverrides(repoRoot, canonicalrouting.CopyRootOutputSingletonConnect(t), runtimecontracts.DefaultPlatformSpecFile(repoRoot))
	if err != nil {
		t.Fatalf("load root-to-singleton conformance fixture: %v", err)
	}
	source := semanticview.Wrap(bundle)
	for _, tc := range []struct {
		name  string
		setup func(*testing.T) (fanInBarrierConformanceStore, *sql.DB)
	}{{name: "sqlite", setup: func(t *testing.T) (fanInBarrierConformanceStore, *sql.DB) {
		backend := storetest.StartSQLiteRuntimeStore(t)
		return backend, storetest.DatabaseForTest(backend)
	}}, {name: "postgres", setup: func(t *testing.T) (fanInBarrierConformanceStore, *sql.DB) {
		_, db, cleanup := testutil.StartPostgres(t)
		t.Cleanup(cleanup)
		return storetest.AdmitPostgresRuntimeStore(t, db), db
	}}} {
		t.Run(tc.name, func(t *testing.T) {
			backend, db := tc.setup(t)
			runID := uuid.NewString()
			ctx := runtimecorrelation.WithRunID(testAuthorActivityContextForBundle(context.Background(), conformanceSourceArtifactFact(t, source)), runID)
			seedFanInBarrierRun(t, ctx, backend, db, source, runID)
			runtime := newFanInBarrierRuntime(t, backend, source)
			constructionCtx := runtimeeffects.WithExecutionMode(ctx, executionmode.Live)
			construction, err := runtime.manager.PrepareFlowInstanceActivation(constructionCtx, runtimepipeline.FlowInstanceActivationRequest{ContractBundle: source, Instance: runtimeflowidentity.Stored(source, ".", runID, runID, runID, ""), OccurredAt: time.Now().UTC()})
			if err != nil {
				t.Fatalf("prepare eager root/receiver tree: %v", err)
			}
			committed, err := runtime.bus.CommitFlowInstanceActivation(constructionCtx, construction)
			if err != nil || !committed.Acknowledged || !committed.Created || len(committed.Children) != 1 {
				t.Fatalf("commit eager root/receiver tree: committed=%#v err=%v", committed, err)
			}
			if err := runtime.manager.FinalizeCommittedFlowInstanceActivation(constructionCtx, committed); err != nil {
				t.Fatalf("finalize eager root/receiver tree: %v", err)
			}
			sourceEntityID := runID
			sourceRoute := events.RouteIdentity{FlowID: source.WorkflowName(), FlowInstance: runID, EntityID: sourceEntityID}.Normalized()
			ctx = runtimedelivery.WithRoute(ctx, events.DeliveryRoute{Recipient: events.MustNodeDeliveryRecipient(conformanceNode(t, "", "root-producer")), Target: events.MustExistingEntityTarget(sourceRoute)})
			routingSource, err := events.NewRootRoutingSource(sourceEntityID)
			if err != nil {
				t.Fatalf("construct root source: %v", err)
			}
			eventID := uuid.NewString()
			parentEventID := uuid.NewString()
			parent := eventtest.ExistingRunRootIngress(parentEventID, events.EventType("custom.root"), "root-producer", "", json.RawMessage(`{"proof":"causal-parent"}`), 0, runID, events.EnvelopeForEntityID(events.EventEnvelope{}, sourceEntityID), time.Now().UTC().Add(-time.Second))
			storetest.CommitSemanticEventWithRoutes(t, ctx, backend, parent, nil, runtimepipelineobligation.ScopeDirect)
			event := eventtest.ChildForProducerWithRoutingSource(eventID, events.EventType("root.ready"), eventtest.Producer(events.EventProducerNode, "root-producer"), "", json.RawMessage(`{"entity_id":"consumer-one"}`), 0, events.EventLineage{RunID: runID, ParentEventID: parentEventID, ExecutionMode: executionmode.Live}, events.EventEnvelope{}, routingSource, time.Now().UTC())
			wantRoute := events.RouteIdentity{FlowID: "consumer", FlowInstance: "consumer", EntityID: runtimeflowidentity.EntityID("consumer")}.Normalized()
			wantOwner := events.MustExistingEntityTarget(wantRoute)
			if sourceEntityID == wantRoute.EntityID {
				t.Fatal("root source and singleton receiver identities must remain distinguishable")
			}
			consumerIdentity := runtimeflowidentity.RunScopedFlowInstance{RunID: runID, Route: runtimeflowidentity.RouteForInstancePath("consumer")}
			before, found, err := runtime.pipeline.Load(ctx, consumerIdentity)
			if err != nil || !found || before.EntityID != wantRoute.EntityID {
				t.Fatalf("singleton receiver must be constructed before first delivery: found:%t instance:%#v err:%v", found, before, err)
			}
			plan, err := runtime.bus.CheckPublishRecipientPlan(ctx, event)
			if err != nil {
				t.Fatalf("preflight root-to-singleton conformance delivery: %v", err)
			}
			if plan.TargetFailure != "" || len(plan.DeliveryRoutes) != 1 || plan.DeliveryRoutes[0].Target != wantOwner || plan.DeliveryRoutes[0].ConnectClaim.Empty() {
				t.Fatalf("root-to-singleton plan = failure:%q routes:%#v, want exact constructed receiver", plan.TargetFailure, plan.DeliveryRoutes)
			}
			if err := runtime.bus.PublishAcknowledged(ctx, event); err != nil {
				t.Fatalf("publish root-to-singleton conformance delivery: %v", err)
			}
			waitCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
			defer cancel()
			if err := runtime.bus.WaitForQuiescence(waitCtx); err != nil {
				t.Fatalf("wait for root-to-singleton execution: %v", err)
			}
			routes, err := backend.ListEventDeliveryRoutes(ctx, eventID)
			if err != nil {
				t.Fatalf("load root-to-singleton routes: %v", err)
			}
			if len(routes) != 1 || routes[0].Target != wantOwner || !routes[0].ConnectClaim.Equal(plan.DeliveryRoutes[0].ConnectClaim) {
				t.Fatalf("persisted root-to-singleton routes = %#v, want exact preflight owner and claim", routes)
			}
			instance, found, err := runtime.pipeline.Load(ctx, consumerIdentity)
			if err != nil {
				t.Fatalf("load materialized singleton receiver: %v", err)
			}
			if !found || strings.TrimSpace(instance.EntityID) != wantRoute.EntityID || !instance.CreatedAt.Equal(before.CreatedAt) {
				t.Fatalf("materialized singleton receiver = found:%t instance:%#v, want entity %s", found, instance, wantRoute.EntityID)
			}
			view, err := backend.LoadOperatorEvent(ctx, eventID)
			if err != nil {
				t.Fatalf("load public root-to-singleton event: %v", err)
			}
			if view.NoDelivery != nil || len(view.DeadLetters) != 0 || len(view.Deliveries) != 1 || view.Deliveries[0].Target.Kind != wantOwner.Code() || view.Deliveries[0].Target.EntityID != wantRoute.EntityID {
				t.Fatalf("public root-to-singleton projection = %#v, want one successful constructed receiver", view)
			}
		})
	}
}

