				t.Fatalf("first audit: %v", err)
			}
			if err := write(); err != nil {
				t.Fatalf("same-owner audit: %v", err)
			}
			record.Identity.RunID, record.RunID = spell(nextRunID), spell(nextRunID)
			if err := write(); err != nil {
				t.Fatalf("moved audit: %v", err)
			}
