				if err != nil {
					return nil, err
				}
				descriptors := make([]string, 0, len(rows))
				for _, row := range rows {
					descriptors = append(descriptors, row.FlowInstance)
				}
				return descriptors, nil
			}
			listTargets := func(paths []string, sourceEntityID string) ([]string, error) {
				rows, err := selected.ListSelectedRunTargetOwnersForScope(ctx, runID, paths, sourceEntityID)
				if err != nil {
					return nil, err
				}
				targets := make([]string, 0, len(rows))
				for _, row := range rows {
					targets = append(targets, row.FlowInstance)
				}
				return targets, nil
			}
			for _, tc := range []struct {
				name      string
				templates []string
				paths     []string
				want      []string
			}{{"template", []string{"review"}, nil, []string{"review/a", "review/b"}}, {"path", nil, []string{"other/c"}, []string{"other/c"}}, {"union", []string{"review"}, []string{"other/c"}, []string{"other/c", "review/a", "review/b"}}, {"duplicate_input", []string{"review", "review"}, []string{"review/a"}, []string{"review/a", "review/b"}}} {
