						t.Fatalf("original owner lost exact-attempt cleanup rights: %v", err)
					}
					if _, err := owner.RebindFlowReadinessSourceSet(ctx, rebind); err == nil {
						t.Fatal("retired attempt revived by re-stamp")
					}
