			}
			rows := []seeded{{uuid.NewString(), "account/current-complete", currentHash, true}, {uuid.NewString(), "account/current-pending", currentHash, false}, {uuid.NewString(), "account/transition-complete", predecessorHash, true}, {uuid.NewString(), "account/transition-pending", predecessorHash, false}}
